```javascript
// 1. 先注册一条连接用于演示
eda.sys_WebSocket.register('嘉立创示例_关闭', 'ws://127.0.0.1:49620',
  () => {},
  () => {
    console.log('连接已建立');
  });

// 2. 等待握手完成
await new Promise(r => setTimeout(r, 1500));

// 3. 以「正常关闭」状态码 1000 关闭连接，并附带原因
eda.sys_WebSocket.close('嘉立创示例_关闭', 1000, '演示完毕');
console.log('已关闭连接（code 1000）');
```
